/**
 * Tools and voice so an agent can own Slack outbound in agentic mode.
 *
 * ```ts
 * // agent/extensions/slack.ts
 * import slackCommunication from "@grok/agent-sdk/extensions/slack-communication";
 *
 * export default slackCommunication();
 * // export default slackCommunication({ tone: "Lead with the merge decision." });
 * ```
 *
 * Pair with `slackChannel({ reply: { mode: "agentic" } })`. The channel
 * acks the parent (`reply.ack`, default `eyes`) and paints the status
 * chip from turn hooks and `actions.requested` (not model `set-status`).
 * It watches `post-update`,
 * `post-file`, `post-card`, `react`, `edit-message`, and
 * `delete-message` (bare or `<namespace>__<name>`) and renders them
 * through the channel Slack client. The tools do not call Slack.
 * `post-update` returns a ts for edit and delete.
 */
import * as z from "zod/v4";
import { defineExtension } from "../../extensions.js";
const slackCommunication = defineExtension({
    root: import.meta.dirname,
    description: "Tools and voice so an agent can own Slack outbound when the channel is agentic.",
    config: z
        .object({
        tone: z.string().trim().min(1).optional(),
    })
        .default({}),
});
export default slackCommunication;
